edits.new:
results = []
for item in iter:
    self.set_value(comp.target.id, item)
    for predicate in comp.ifs:
        cond = _unwrap_if_constexpr(self.visit(predicate))
        if _is_triton_tensor(cond) or type(cond) not in _condition_types:
            raise self._unsupported(
                predicate, "comprehension conditions must be compile-time scalar values")
        if not cond:
            break
    else:
        results.append(self.visit(node.elt))
return tl_tuple(results)
